/* 查询：按关键词（公司名/品类/城市）+ 国家 + 展会 过滤，返回最多 lim 条
   kw 支持中英文；cc 传 ISO3（如 "CHN"）；evId 传展会 ID（如 "AUTOMECHANIKA"） */
window.FAL_EXPO_Q = function (kw, cc, evId, lim) {
  lim = lim || 50;
  var D = window.FAL_EXPO_DICT, R = window.FAL_EXPO_ROWS;
  var q = (kw || "").toLowerCase().trim();
  var ccIx = cc ? D.cc.indexOf(cc) : -1;
  var evIx = evId ? D.ev.indexOf(evId) : -1;
  if (cc && ccIx < 0) return [];
  if (evId && evIx < 0) return [];
  var out = [];
  for (var i = 0; i < R.length; i++) {
    var r = R[i];
    if (ccIx >= 0 && r[1] !== ccIx) continue;
    if (evIx >= 0 && r[6] !== evIx) continue;
    if (q) {
      var hay = (r[0] + " " + r[2] + " " + D.k[r[7]]).toLowerCase();
      if (hay.indexOf(q) < 0) continue;
    }
    out.push({ nm: r[0], cc: D.cc[r[1]], city: r[2], tel: r[3], mail: r[4],
               web: r[5], ev: D.ev[r[6]], k: D.k[r[7]] });
    if (out.length >= lim) break;
  }
  return out;
};

/* 反查：某公司名是否出现在展会名录里（企业真实性证据）。
   返回命中的条目数组，空数组 = 未命中（**不等于不存在**，只等于「未在本名录内」） */
window.FAL_EXPO_LOOKUP = function (name) {
  var q = (name || "").toLowerCase().trim();
  if (q.length < 3) return [];
  var D = window.FAL_EXPO_DICT, R = window.FAL_EXPO_ROWS, out = [];
  for (var i = 0; i < R.length; i++) {
    var n = R[i][0].toLowerCase();
    if (n.indexOf(q) >= 0 || q.indexOf(n) >= 0) {
      out.push({ nm: R[i][0], cc: D.cc[R[i][1]], city: R[i][2], tel: R[i][3],
                 mail: R[i][4], web: R[i][5], ev: D.ev[R[i][6]], k: D.k[R[i][7]] });
      if (out.length >= 5) break;
    }
  }
  return out;
};
